SELECT EXISTS(SELECT 1 FROM pg_policies WHERE tablename='ranking_jugadores' AND policyname='nations_ranking_jugadores_read_guard' AND permissive='RESTRICTIVE') AS ranking_child_privacy_guard,
 EXISTS(SELECT 1 FROM pg_policies WHERE tablename='clasificaciones' AND policyname='nations_clasificaciones_read_guard' AND permissive='RESTRICTIVE') AS classification_child_privacy_guard,
 EXISTS(SELECT 1 FROM pg_policies WHERE tablename='games' AND policyname='nations_games_read_guard' AND permissive='RESTRICTIVE') AS games_privacy_guard,
 EXISTS(SELECT 1 FROM pg_policies WHERE tablename='scoreboard_partidos' AND policyname='nations_scoreboard_read_guard' AND permissive='RESTRICTIVE') AS scoreboard_privacy_guard,
 NOT has_table_privilege('anon','public.torneo_nations_planes','SELECT') AS private_plan_anon_denied,
 NOT has_table_privilege('authenticated','public.torneo_nations_planes','SELECT') AS private_plan_client_denied,
 EXISTS(SELECT 1 FROM pg_policies WHERE tablename='equipos' AND policyname='nations_equipos_read_guard' AND permissive='RESTRICTIVE') AS roster_privacy_guard,
 EXISTS(SELECT 1 FROM pg_policies WHERE tablename='partidos' AND policyname='nations_partidos_read_guard' AND permissive='RESTRICTIVE') AS matches_privacy_guard,
 EXISTS(SELECT 1 FROM pg_policies WHERE tablename='tabla_puntos' AND policyname='nations_puntos_read_guard' AND permissive='RESTRICTIVE') AS points_embargo_guard,
 EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='torneos' AND column_name='plan_nations' AND data_type='jsonb') AS event_plan_column,
 EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='torneo_nations_programacion' AND column_name='inicio' AND data_type='timestamp with time zone') AS schedule_timezone_type,
 to_regprocedure('public.guardar_plan_nations(bigint,uuid,text,bigint,uuid,text,jsonb)') IS NOT NULL AS atomic_rpc_present,
 to_regprocedure('public.leer_estado_nations(bigint)') IS NOT NULL AS consistent_read_present,
 to_regprocedure('public.exportar_acta_nations(bigint,uuid,bigint)') IS NOT NULL AS export_snapshot_present,
 NOT has_function_privilege('authenticated','public.guardar_plan_nations(bigint,uuid,text,bigint,uuid,text,jsonb)','EXECUTE') AS client_write_rpc_denied,
 NOT has_function_privilege('anon','public.guardar_plan_nations(bigint,uuid,text,bigint,uuid,text,jsonb)','EXECUTE') AS anonymous_write_rpc_denied,
 NOT has_function_privilege('authenticated','public.leer_estado_nations(bigint)','EXECUTE') AS raw_graph_private,
 NOT has_function_privilege('anon','public.exportar_acta_nations(bigint,uuid,bigint)','EXECUTE') AS acta_private,
 EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.scoreboard_partidos'::regclass AND tgname='proteger_marcador_nations' AND NOT tgisinternal) AS marker_schedule_guard,
 EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.reservas'::regclass AND tgname='proteger_reserva_nations' AND NOT tgisinternal) AS reservation_schedule_guard,
 EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.clases_horarios'::regclass AND tgname='proteger_horario_clase_nations' AND NOT tgisinternal) AS class_schedule_guard;
